// Cloudflare Pages Function — verifies a Stripe Checkout Session before
// releasing the Kit PDF. The file is never reachable as a plain static
// asset; it only leaves this function after Stripe confirms payment for
// the exact Kit price, so guessing/sharing this URL alone buys nothing.
//
// Requires a STRIPE_SECRET_KEY environment variable/secret set on the
// Cloudflare Pages project (Settings > Environment variables, or
// `wrangler pages secret put STRIPE_SECRET_KEY`). Never commit the key.

const KIT_PRICE_ID = "price_REEMPLAZAR_CON_EL_ID_REAL";

export async function onRequestGet(context) {
  const { request, env } = context;
  const url = new URL(request.url);
  const sessionId = url.searchParams.get("session_id");

  if (!sessionId) {
    return new Response("Falta session_id", { status: 400 });
  }
  if (!env.STRIPE_SECRET_KEY) {
    return new Response("Falta configurar STRIPE_SECRET_KEY", { status: 500 });
  }

  const stripeRes = await fetch(
    `https://api.stripe.com/v1/checkout/sessions/${encodeURIComponent(sessionId)}?expand[]=line_items`,
    { headers: { Authorization: `Bearer ${env.STRIPE_SECRET_KEY}` } }
  );

  if (!stripeRes.ok) {
    return new Response("Sesion de pago no valida", { status: 402 });
  }

  const session = await stripeRes.json();

  if (session.payment_status !== "paid") {
    return new Response("El pago todavia no esta confirmado", { status: 402 });
  }

  const purchasedKit = (session.line_items?.data || []).some(
    (item) => item.price && item.price.id === KIT_PRICE_ID
  );

  if (!purchasedKit) {
    return new Response("Esta compra no incluye el Kit de Mudanza", { status: 403 });
  }

  const pdfBase64 =
    "";

  const binary = atob(pdfBase64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

  return new Response(bytes, {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": 'attachment; filename="Kit-Mudanza-Suiza.pdf"',
      "Cache-Control": "no-store",
    },
  });
}
